pyq_focus = [
 "Unit 3 se NET mein sabse zyada author-work matching aata hai: kaun sa novel kisne likha aur kab.",
 "Characters ko novel se match karna (Becky Sharp, Heathcliff, Okonkwo, Saleem Sinai) har cycle ka favourite hai.",
 "Chronology questions: Dickens, Hardy, Woolf, Achebe aur 18th century novels ka order yaad rakho, approx decade kaafi hai.",
 "Famous opening lines aur epigraphs (Call me Ishmael, It is a truth universally acknowledged) baar baar pooche gaye hain.",
 "Booker aur Nobel winners, khaas kar Indian aur African writers, saal ke saath ratt lo.",
 "Narrative theory: Forster (story vs plot, flat vs round), Booth (unreliable narrator), Genette, Bakhtin, Watt ke terms zaroor padho.",
 "Short story mein Poe ka single effect, Gogol, Maupassant, Chekhov, O. Henry, Mansfield aur Indian writers (Premchand, Manto, Narayan) aate hain.",
 "Indian English novel (Big Three, Partition novels, Rushdie ke baad wale) se 2-3 sawal pakke hote hain.",
 "Taiyari ka tareeka: har author ki 3-4 main works, 1 character, 1 famous line ka chhota card banao aur roz 20 MCQ lagao.",
]

easy = [
 {"title":"Precursors and the Rise of the Novel",
  "story":"Novel ek naya khilona tha jo 18th century England mein aaya. Pehle log lambi allegory padhte the, jaise Bunyan ki The Pilgrim's Progress. Phir Defoe ne Robinson Crusoe likha, ek aadmi jo island par akela reh gaya, bilkul real lagne wali kahani. Richardson ne Pamela likha, poori kahani chitthiyon mein, jaise WhatsApp chats padh rahe ho. Fielding ko Pamela pasand nahi aaya, toh usne Shamela naam se uska mazaak udaya aur phir Joseph Andrews aur Tom Jones likhe. Sterne ki Tristram Shandy itni ulti-seedhi hai ki hero ka janam bhi der se hota hai.",
  "trick":"DRF = Defoe, Richardson, Fielding, jaise DRF ki teen bhai ki dukaan: Crusoe (1719), Pamela (1740), Tom Jones (1749). Ian Watt ne inhi teen par Rise of the Novel (1957) likhi."},
 {"title":"Later 18th Century: Gothic, Sentimental and Romantic-era Fiction",
  "story":"Socho ek purana haveli jahan raat ko darwaze apne aap khulte hain, yahi Gothic novel hai. Walpole ki The Castle of Otranto (1764) pehla Gothic novel tha. Radcliffe darr dikhati thi par end mein sab samjha deti thi, isko explained supernatural kehte hain. Phir Jane Austen aayi jo gaon ke 3-4 parivaron ki shaadi aur samajh ki kahaniyan likhti thi, jaise mohalle ki aunty jo sab jaanti hai. Walter Scott ne Waverley se historical novel shuru kiya. Mary Shelley ne Frankenstein mein ek scientist dikhaya jo naya insaan bana deta hai.",
  "trick":"Gothic order: Otranto-Vathek-Udolpho-Monk = 'O Very Ugly Monk' (1764, 1786, 1794, 1796). Austen ke 6 novels: 'Sense Pride Mansfield Emma, Northanger Persuasion' = SPM-E-NP."},
 {"title":"Victorian Novel I: Dickens, Thackeray, Brontes, Gaskell",
  "story":"Victorian England mein factories, garibi aur bachche kaam karte the. Dickens ne in sab par bade bade novels likhe jo magazines mein kisto mein chhapte the, jaise TV serial ke episodes. Oliver Twist khana maangta hai, Pip ko ameer banne ke sapne dikhte hain. Thackeray ki Vanity Fair mein koi hero hi nahi, bas chalak Becky Sharp. Teen Bronte behnein mard naam (Currer, Ellis, Acton Bell) se likhti thi, jaise ghar ki ladkiyan ghoonghat mein. Gaskell ne mill workers ki dukh bhari zindagi dikhayi.",
  "trick":"Bronte naam: C-E-A = Currer, Ellis, Acton: Charlotte-Jane Eyre, Emily-Wuthering Heights, Anne-Agnes Grey. Teeno 1847 mein, '47 ki teen behnein'."},
 {"title":"Victorian Novel II: Eliot, Trollope, Hardy and Late Victorians",
  "story":"George Eliot asal mein ek aurat thi, Mary Ann Evans, jisne mard naam rakha taaki log seriously padhein. Uska Middlemarch ek pura chhota shehar dikhata hai, jaise poore mohalle ka CCTV. Hardy ne Wessex naam ka nakli ilaaka banaya aur wahan kismat se haare logon ki kahaniyan likhi. Tess aur Jude ke saath itna bura hua ki log naraz ho gaye, aur Hardy ne novel likhna chhod kar poetry pakad li. Late Victorian zamane mein Dracula, Dr Jekyll aur Dorian Gray jaise darawne aur ajeeb kirdaar aaye.",
  "trick":"Hardy order: 'Far Return Mayor Tess Jude' = 'Far se Return karke Mayor ne Tess aur Jude ko dekha' (1874, 1878, 1886, 1891, 1895)."},
 {"title":"Transition: James, Conrad and the Edwardians",
  "story":"Yeh 1900 ke aas paas ka bridge hai, purane Victorian aur naye Modernist novel ke beech. Henry James Americans ko Europe bhejta tha aur dekhta tha unke dimaag mein kya chal raha hai. Conrad, jo Polish tha, samundar aur Africa ki kahaniyan English mein likhta tha; Heart of Darkness mein Marlow Kurtz ko dhoondhne jata hai. Forster ne India par A Passage to India likha, jahan Marabar Caves mein kuch hua par pata nahi kya. Wells, Bennett aur Galsworthy bahar ki cheezein gin gin kar likhte the, isliye Woolf ne unko materialists kaha.",
  "trick":"Conrad ka mantra 'to make you see' = Conrad ka chashma. Forster ka mantra 'Only connect' = Forster ka charger (Howards End, 1910)."},
 {"title":"Modernist Novel: Joyce, Woolf, Lawrence",
  "story":"Modernist novel mein kahani bahar kam aur dimaag ke andar zyada hoti hai. Jaise tum class mein baithe ho par dimaag mein ghar, khana, dost sab ghoom rahe hain, isko stream of consciousness kehte hain. Joyce ka Ulysses sirf ek din, 16 June 1904, Dublin mein chalta hai. Woolf ki Mrs Dalloway bhi ek din mein party ki taiyari karti hai. Lawrence ne maa-bete aur pyaar ke rishton par Sons and Lovers likha. Yeh writers purani seedhi kahani todkar nayi shape bana rahe the.",
  "trick":"'J-W-L = Jaldi Woh Ladka': Joyce (Ulysses 1922), Woolf (Mrs Dalloway 1925), Lawrence (Sons and Lovers 1913). 1922 = Ulysses + The Waste Land, modernism ka 'magic year'."},
 {"title":"1930s to Post-war British Fiction",
  "story":"World War ke baad duniya darr aur sawalon se bhari thi. Orwell ne Animal Farm mein jaanwaron ke zariye bataya ki sarkar kaise dhoka deti hai, aur 1984 mein Big Brother sab dekh raha hai, jaise har gali mein camera. Golding ne Lord of the Flies mein dikhaya ki bachche bhi island par jungli ban jaate hain. Kingsley Amis aur Angry Young Men gusse wale middle class naujawan ki kahani likhte the. Murdoch, Lessing, Spark aur Fowles ne novel ko aur naye tareeke se likha.",
  "trick":"Orwell ka 1949 aur 1984 ulta yaad rakho: '49 likha, 84 ka darr'. Golding ka Piggy ka chashma = aag, jab chashma toota toh civilisation tooti."},
 {"title":"Contemporary British Fiction (1980s onward)",
  "story":"1980 ke baad British novel mein bahar se aaye log aur purani history ko naye tareeke se dekhna shuru hua. Ishiguro ka butler Stevens apni yaadon mein khoya rehta hai, jaise dada ji jo purani naukri ki baat karte hain. McEwan ki Atonement mein ek ladki ka chhota sa jhooth sabki zindagi badal deta hai. Mantel ne Henry VIII ke darbar par trilogy likhi aur do baar Booker jeeti. Kai novels apne aap ko novel bata dete hain, isko metafiction kehte hain.",
  "trick":"Double Booker queen = Mantel (Wolf Hall 2009, Bring Up the Bodies 2012): 'Mantel ne do baar mantel (trophy shelf) bhara'. Ishiguro Nobel 2017 = 'Ishi-17'."},
 {"title":"American Novel: 19th Century to 1920",
  "story":"America naya desh tha aur apni kahani dhoondh raha tha. Cooper ne jungle aur Native Americans ki kahani di, Hawthorne ne Puritan samaj mein ek aurat Hester ko laal 'A' pehna kar sharam dikhayi. Melville ka Captain Ahab ek safed whale ke peeche pagal hai, jaise koi ek cheez ke peeche sab kuch lutaa de. Mark Twain ka Huck ek ladka hai jo raft par Mississippi nadi mein bhagta hai, aur gaon wali boli mein baat karta hai. Baad mein Crane, Dreiser jaise naturalists ne dikhaya ki insaan halaat ka ghulam hai.",
  "trick":"Ameriki 1850-51 = 'Scarlet aur Whale', The Scarlet Letter 1850, Moby-Dick 1851, dono ek saath, aur Moby-Dick Hawthorne ko dedicated."},
 {"title":"American Novel: 20th Century to Contemporary",
  "story":"20th century America mein jazz, party aur paisa tha, par andar khalipan bhi. Fitzgerald ka Gatsby badi parties deta hai sirf ek ladki Daisy ke liye, jaise koi shaadi mein sirf ek insaan ko impress karne ke liye DJ bulaye. Hemingway chhote seedhe vakya likhta tha, baaki matlab paani ke neeche chhupe iceberg jaisa. Faulkner ne ek hi parivar ko alag alag dimaagon se dikhaya. Phir Black writers jaise Ellison, Morrison aur Walker ne apni awaaz di, aur Vonnegut, Pynchon ne postmodern khel khele.",
  "trick":"Nobel American novelists ka order: 'Lewis-Faulkner-Hemingway-Steinbeck-Bellow-Morrison' = 'LFHSBM: Lalu Fauji Hamesha Sabko Bada Maante' (1930, 1949, 1954, 1962, 1976, 1993)."},
 {"title":"Indian English Novel I: Beginnings to 1970s",
  "story":"Indian English novel ki shuruaat Bankim ke Rajmohan's Wife (1864) se hoti hai. Phir 1930s mein teen bade naam aaye: Anand, Narayan aur Raja Rao, inko Big Three kehte hain. Anand ne garib aur achhoot Bakha ka ek din dikhaya. Narayan ne Malgudi naam ka pyara sa chhota shehar banaya, jaise apna kasba. Raja Rao ne Kanthapura gaon mein Gandhi ji ke andolan ko daadi-nani ki kahani ki tarah sunaya. Partition par Khushwant Singh ka Train to Pakistan bahut zaroori hai.",
  "trick":"Big Three = 'ANR' jaise ANR film star: Anand (Untouchable 1935), Narayan (Swami 1935), Rao (Kanthapura 1938). Do 1935 mein, ek 1938 mein."},
 {"title":"Indian English Novel II: Rushdie and After",
  "story":"1981 mein Rushdie ka Midnight's Children aaya, jismein Saleem 15 August 1947 ki aadhi raat ko paida hota hai, bilkul India ke saath. Iske baad Indian English novel duniya bhar mein famous ho gaya. Amitav Ghosh ne borders aur yaadon par The Shadow Lines likha. Arundhati Roy ki The God of Small Things Kerala ke judwan bachchon ki dukh bhari kahani hai. Kiran Desai aur Aravind Adiga ne bhi Booker jeeta. Adiga ka Balram ek driver hai jo Chinese Premier ko chitthiyan likhta hai.",
  "trick":"Indian Booker train: '81 Rushdie, '97 Roy, '06 Kiran, '08 Adiga' = 'R-R-K-A, Rail Ruki Kaise Achanak'. (Naipaul 1971 Trinidad wale.)"},
 {"title":"African Fiction",
  "story":"Angrezon ne Africa ko apne novels mein jungli dikhaya tha. Achebe ne jawab mein Things Fall Apart likha, jismein Igbo samaj ki apni izzat, rasm aur kanoon hain. Okonkwo ek takatwar aadmi hai jo naye zamane ke aage toot jata hai. Ngugi ne baad mein English chhod kar apni Gikuyu bhasha mein likhna shuru kiya, jaise koi Hindi mein hi likhne ki kasam kha le. South Africa se Gordimer aur Coetzee ne apartheid ka dard likha. Soyinka pehle African the jinhe Nobel mila.",
  "trick":"Achebe ki trilogy order: 'Things-No-Arrow' = 'Things No Arrow' (1958, 1960, 1964): pehle cheezein toot-ti hain, phir chain nahi, phir teer."},
 {"title":"Caribbean, Canadian, Australian and Other Postcolonial Fiction",
  "story":"Angrezi raj sirf India mein nahi tha, Caribbean, Canada, Australia sab jagah tha. Trinidad ke Naipaul ne Mr Biswas ki kahani likhi jo bas apna ek ghar chahta hai, jaise har middle class aadmi ka sapna. Sam Selvon ne London aaye Caribbean logon ki boli mein The Lonely Londoners likha. Canada ki Atwood ne Handmaid's Tale mein ek darawni sarkar Gilead dikhayi. Colombia ke Marquez ne magic aur sach ko mila kar Macondo gaon banaya.",
  "trick":"'Biswas ka Bungalow' = A House for Mr Biswas (1961). Atwood ki 2 Bookers: 2000 aur 2019 = 'Atwood double, 2000 + 19'."},
 {"title":"Short Story: Theory and Western Masters",
  "story":"Short story ek baar mein baith kar padhi jaane wali kahani hai, jaise chai khatam hone tak ki kahani. Poe ne kaha ki poori kahani ka ek hi asar hona chahiye, single effect. Maupassant aur O. Henry end mein twist dete hain, jaise Necklace mein haar nakli nikalta hai. Chekhov ki kahaniyon mein bada plot nahi, bas ek mood hota hai. Joyce ki Dubliners mein achanak samajh aane wala pal hota hai, jise epiphany kehte hain.",
  "trick":"Twist wale do: 'M aur O' = Maupassant (Necklace 1884) aur O. Henry (Gift of the Magi 1905). Mood wala ek: Chekhov = 'Chai jaisa mood'."},
 {"title":"Indian Short Story (English and in Translation)",
  "story":"Indian short story mein gaon, garibi, partition aur aurat ki chhupi ichhaon ki kahaniyan hain. Premchand ki Kafan mein baap-beta kafan ke paise se sharab pee jaate hain, kyunki bhookh ne unhe pathar bana diya. Manto ki Toba Tek Singh mein ek paagal aadmi partition ki line par hi mar jaata hai. Narayan ki Malgudi Days chhote shehar ki halki mazedaar kahaniyan hain. Ruskin Bond pahadon aur trains ki pyaari kahaniyan likhte hain. Mahasweta Devi ki Draupadi ko Spivak ne English mein laya.",
  "trick":"Urdu ke teen: 'Premchand-Manto-Chughtai = PMC': Kafan, Toba Tek Singh, Lihaaf. Lihaaf = rajai = court case (1942)."},
 {"title":"Narrative Theory and Criticism of the Novel",
  "story":"Narrative theory batati hai ki kahani kaise banti hai, jaise recipe batati hai ki biryani kaise banti hai. Forster ne kaha raja mara phir rani mari, yeh story hai, par rani dukh se mari, yeh plot hai kyunki isme 'kyun' hai. Booth ne bataya ki kuch narrators jhooth ya galat samajh se kahani sunate hain. Genette ne flashback ko analepsis aur flash-forward ko prolepsis naam diya. Bakhtin ne kaha novel mein kai awaazein ek saath bolti hain, jaise joint family ka dinner table.",
  "trick":"'Forster ka Flat-Round, Booth ka Bura (unreliable) Narrator, Genette ka Gyaan (focalization), Bakhtin ka Bazaar (polyphony)'."},
 {"title":"Famous Opening Lines of Novels",
  "story":"Novel ki pehli line hi uski pehchaan hoti hai, jaise film ka pehla dialogue. 'Call me Ishmael' sunte hi Moby-Dick yaad aata hai. Austen ki pehli line mazaak mein kehti hai ki ameer kunwara ladka biwi dhoondh raha hai. 1984 mein ghadi tera baja rahi hai, toh pata chal jaata hai kuch gadbad duniya hai. NET aksar pehli line dekar novel poochta hai, isliye inhe gaane ki tarah gaa kar yaad karo.",
  "trick":"'Ishmael, Truth, Thirteen' teen sabse famous: Call me Ishmael (Moby-Dick), truth universally acknowledged (P&P), clocks striking thirteen (1984)."},
]
